& =\left[\left(\frac{3}{2}\right)\left(-\frac{2}{3}\right)+\left(\frac{7}{2}\right)\left(\frac{2}{3}\right)+\left(\frac{1}{2}\right)\left(\frac{1}{3}\right)\right]\left(-\frac{2}{3} \mathbf{i}+\frac{2}{3} \mathbf{i}+\frac{1}{3} \mathbf{k}\right) \\
& =\left(\frac{3}{2}\right)\left(-\frac{2}{3} \mathbf{i}+\frac{2}{3} \mathbf{j}+\frac{1}{3} \mathbf{k}\right) \\
& =-\mathbf{i}+\mathbf{j}+\frac{1}{2} \mathbf{k}
\end{aligned}
$$
\end{itemize}
