\overrightarrow{D E} & =\left[\overrightarrow{D A} \cdot \frac{-18 \mathbf{i}-36 \mathbf{j}+36 \mathbf{k}}{\sqrt{(-18)^{2}+(-36)^{2}+36^{2}}}\right]\left[\frac{-18 \mathbf{i}-36 \mathbf{j}+36 \mathbf{k}}{\sqrt{(-18)^{2}+(-36)^{2}+36^{2}}}\right] \\
& =\left[(\mathbf{i}+11 \mathbf{j}-11 \mathbf{k}) \cdot \frac{-18 \mathbf{i}-36 \mathbf{j}+36 \mathbf{k}}{54}\right]\left[\frac{-18 \mathbf{i}-36 \mathbf{j}+36 \mathbf{k}}{54}\right] \\
& =5 \mathbf{i}+10 \mathbf{j}-10 \mathbf{k}
\end{aligned}
$$
\item[（b）] （i）Let $A F: F C=t:(1-t)$ ，where $0<t<1$ ．
設 $A F: F C=t:(1-t)$ ，其中 $0<t<1$ 。
Since $\overrightarrow{D F}$ is perpendicular to $\overrightarrow{A C}$ ，we have
由於 $\overrightarrow{D F}$ 垂直於 $\overrightarrow{A C}$ ，可得
$$
\begin{aligned}
\overrightarrow{D F} \cdot \overrightarrow{A C} & =0 \\
(\overrightarrow{D A}+\overrightarrow{A F}) \cdot \overrightarrow{A C} & =0 \\
(\overrightarrow{D A}+t \overrightarrow{A C}) \cdot \overrightarrow{A C} & =0 \\
{[(\mathbf{i}+11 \mathbf{j}-11 \mathbf{k})+t(4 \mathbf{i}+2 \mathbf{j}+4 \mathbf{k})] \cdot(4 \mathbf{i}+2 \mathbf{j}+4 \mathbf{k}) } & =0 \\
(1+4 t)(4)+(11+2 t)(2)+(4 t-11)(4) & =0 \\
36 t-18 & =0 \\
t & =\frac{1}{2}
\end{aligned}
$$
Thus，we have 由此，可得
$$
\overrightarrow{D F}=3 \mathbf{i}+12 \mathbf{j}-9 \mathbf{k}
$$
\end{itemize}
\begin{itemize}
\begin{itemize}
\item[（ii）]
$$
\begin{aligned}
\overrightarrow{E F} & =\overrightarrow{D F}-\overrightarrow{D E} \\
& =(3 \mathbf{i}+12 \mathbf{j}-9 \mathbf{k})-(5 \mathbf{i}+10 \mathbf{j}-10 \mathbf{k}) \\
& =-2 \mathbf{i}+2 \mathbf{j}+\mathbf{k}
\end{aligned}
$$
$$
\begin{aligned}
\overrightarrow{E F} \cdot \overrightarrow{A C} & =(-2 \mathbf{i}+2 \mathbf{j}+\mathbf{k}) \cdot(4 \mathbf{i}+2 \mathbf{j}+4 \mathbf{k}) \\
& =(-2)(4)+(2)(2)+(1)(4) \\
& =0
\end{aligned}
$$
Thus， $\overrightarrow{E F}$ is perpendicular to $\overrightarrow{A C}$ ．
因此， $\overrightarrow{E F}$ 垂直於 $\overrightarrow{A C}$ 。
\end{itemize}
\item[（c）] Note that the required angle is $\angle D F E$ ．
留意所求的角為 $\angle D F E$ 。
$$
\begin{aligned}
\cos \angle D F E & =\frac{\overrightarrow{D F} \cdot \overrightarrow{E F}}{|\overrightarrow{D F}||\overrightarrow{E F}|} \\
& =\frac{(3 \mathbf{i}+12 \mathbf{j}-9 \mathbf{k}) \cdot(-2 \mathbf{i}+2 \mathbf{j}+\mathbf{k})}{\sqrt{3^{2}+12^{2}+(-9)^{2}} \sqrt{(-2)^{2}+2^{2}+1^{2}}} \\
& =\frac{9}{9 \sqrt{26}} \\
& =\frac{\sqrt{26}}{26}
\end{aligned}
$$
Thus，the required angle is $\cos ^{-1}\left(\frac{\sqrt{26}}{26}\right)$ ．
因此，所求的角為 $\cos ^{-1}\left(\frac{\sqrt{26}}{26}\right)$ 。
\end{itemize}

